import logging
import time

from ta_ue_plugin_android.uepc.inon_blocking_reader import INonBlockingReader
from ta_ue_plugin_android.uepc.ue_pc_logger import RemoteAddrAdapter


class SshNonBlockingReader(INonBlockingReader):
    """Used for reading output from SSH streams"""

    def __init__(self, stdout, stderr, ssh_client, hostname=''):
        """

        :param stdout:
        :param stderr:
        :param ssh_client:
        """
        self.stdout = stdout
        self.stderr = stderr
        self._set_stdout_stderr_to_binary_mode()
        self.chan = self.stdout.channel
        self.chan.settimeout(5)  # 5 seconds timeout
        self.ssh_client = ssh_client
        self.hostname = hostname
        raw_logger = logging.getLogger("ute_ue.uepc")
        self.logger = RemoteAddrAdapter(remote=hostname, logger=raw_logger, extra={'area': 'SSH'})

    def has_line_without_blocking(self):
        """
        If next line is ready to read without blocking.
        :return: bool
        """
        return self.chan.recv_ready()

    def has_data_in_stdout_buffer(self):
        """
        If there is a data in buffer to be read
        :return: bool
        """
        return len(self.stdout._rbuffer) > 0

    def read_lines(self, timeout=2):
        """
        Reads lines ot throw exception.
        :return: [string]
        """
        end_time = time.time() + timeout
        while not self._has_data_in_stdout() and not self.stdout.channel.closed:
            if time.time() > end_time:
                break
            self.logger.debug('Waiting for cmd output: {}'.format(time.time()))
            time.sleep(0.2)
            continue
        result = self._get_stdout_lines_in_list()
        self.logger.debug("_get_stdout_lines_in_list result: {}".format(result))
        # bug fix:
        # self.is_finish() tells if channel is closed
        # but channel may be closed and some data is in stdout's read buffer
        while self.is_finish():
            lines = self.stdout.readlines()
            if lines:
                self.logger.debug("ssh's stdout has unflushed data after ssh-channel close")
                result += [self._ensure_no_line_ending(line) for line in lines]
            else:
                break
        return result

    def _get_stdout_lines_in_list(self):
        result = []
        while self._has_data_in_stdout():
            line = (self.stdout.readline()).decode("utf-8", errors='ignore')
            line = self._ensure_no_line_ending(line)
            result.append(line)
        return result

    def _has_data_in_stdout(self):
        """
        Checks if there is a chan.recv_ready() or has some data in rbuffer.
        Sometimes it has rbuffer despite not having recv_ready
        """
        return self.has_line_without_blocking() or self.has_data_in_stdout_buffer()

    def really_read_lines(self):
        """
        Forces read after close. Sometimes returns some lines.
        :return:
        """
        lines = self.stdout.readlines()
        if lines:
            stripped_lines = []
            for line in lines:
                stripped_line = self._ensure_no_line_ending(line)
                self.logger.debug("[REALLY] {}".format(stripped_line), extra={'direction': '<'})
                stripped_lines.append(stripped_line)
            return stripped_lines
        return []

    def is_finish(self):
        """
        Is EOF reached.
        :return:
        """
        result = not self._has_data_in_stdout() and self.chan.closed
        return result

    def _ensure_no_line_ending(self, line):
        return line.rstrip()

    def close(self):
        """Close ssh session."""
        self.logger.debug("Closing SSH connection")
        self.ssh_client.close()

    def _set_stdout_stderr_to_binary_mode(self):
        self.stdout._set_mode('b')
        self.stderr._set_mode('b')
